package com.opensocket.aievent.core.issuetracking.application.relay;
import java.time.*; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import com.opensocket.aievent.core.issuetracking.relay.*;
@Service public class CanonicalRelationService { private final RelayGovernanceRepository repository; private final RelayEventLedger ledger; public CanonicalRelationService(RelayGovernanceRepository repository,RelayEventLedger ledger){this.repository=repository;this.ledger=ledger;}
 @Transactional public CanonicalIssueRelation create(String tenantId,String relationType,String parentTaskId,String childTaskId,String sourceLinkId,String targetLinkId,String actor,String correlationId){OffsetDateTime now=OffsetDateTime.now(ZoneOffset.UTC);CanonicalIssueRelation relation=new CanonicalIssueRelation(tenantId,"canonical-relation-"+UUID.randomUUID(),relationType,parentTaskId,childTaskId,sourceLinkId,targetLinkId,CanonicalRelationStatus.ACTIVE,1,now,now,correlationId);repository.saveRelation(relation);ledger.append(tenantId,"CANONICAL_RELATION",relation.relationId(),RelayEventType.RELATION_CREATED,actor,"CANONICAL_RELATION_CREATED","{}",correlationId);return relation;}
 public Optional<CanonicalIssueRelation> find(String tenantId,String relationId){return repository.findRelation(tenantId,relationId);} public List<CanonicalIssueRelation> list(String tenantId,CanonicalRelationStatus status,int limit){return repository.listRelations(tenantId,status,limit(limit));} private int limit(int n){return Math.max(1,Math.min(n,1000));}
}
